const uint32_t *get_weather_icon(const char *id) {
    for (uint8_t i = 0; i < TOTAL_WEATHER_ICONS; i++) {
        if (strcmp(weather_icons[i].id, id) == 0) {
            return weather_icons[i].bitmap;
        }
    }

    return NULL;
}